import { readFileSync } from "node:fs";

const SCHEMA_PREFIX = "cfg-schema-v";
const SUPPORTED_SCHEMA = 4;
const SCHEMA_KEY = "schema";

const isPlainObject = (v) =>
  v !== null && typeof v === "object" && !Array.isArray(v);

function readLayerFile(path, layer) {
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw new Error(`config: cannot read ${layer} file ${path}: ${err.message}`);
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`config: invalid JSON in ${layer} file ${path}: ${err.message}`);
  }
  if (!isPlainObject(data)) {
    throw new Error(`config: ${layer} file ${path} must contain a JSON object`);
  }
  return data;
}

function checkSchemaVersion(data, layer, path) {
  if (!(SCHEMA_KEY in data)) return;
  const declared = data[SCHEMA_KEY];
  const match =
    typeof declared === "string" && declared.startsWith(SCHEMA_PREFIX)
      ? /^\d+$/.exec(declared.slice(SCHEMA_PREFIX.length))
      : null;
  if (!match) {
    throw new Error(`config: ${layer} file ${path} has malformed schema "${declared}"`);
  }
  if (Number(match[0]) > SUPPORTED_SCHEMA) {
    throw new Error(
      `config: ${layer} file ${path} declares ${declared}, newer than ${SCHEMA_PREFIX}${SUPPORTED_SCHEMA}`,
    );
  }
}

// Merge `input` over `target`. Unknown keys (absent from the defaults tree)
// warn with their key path and layer, and are dropped from the merged result.
function mergeLayer(target, input, known, layer, sources, warn, prefix = "") {
  for (const [key, value] of Object.entries(input)) {
    const path = prefix + key;
    if (prefix === "" && key === SCHEMA_KEY) continue;
    if (!Object.hasOwn(known, key)) {
      warn(`config: unknown key "${path}" in ${layer} layer`);
      continue;
    }
    if (isPlainObject(known[key]) && isPlainObject(value)) {
      mergeLayer(target[key], value, known[key], layer, sources, warn, `${path}.`);
    } else {
      target[key] = value;
      sources[path] = layer;
    }
  }
}

function seed(defaults, sources, prefix = "") {
  const out = {};
  for (const [key, value] of Object.entries(defaults)) {
    const path = prefix + key;
    if (isPlainObject(value)) {
      out[key] = seed(value, sources, `${path}.`);
    } else {
      out[key] = value;
      sources[path] = "default";
    }
  }
  return out;
}

/**
 * Load config from three layers: defaults, project file, user file.
 * Returns { config, sources } where sources maps each dotted key path to
 * the layer that set its value ("default" | "project" | "user").
 *
 * Unknown keys warn (via `warn`) and are ignored; files declaring a schema
 * newer than cfg-schema-v4 are refused.
 */
export function loadConfig({
  defaults = {},
  projectPath,
  userPath,
  warn = (msg) => console.warn(msg),
} = {}) {
  const sources = {};
  const config = seed(defaults, sources);
  const layers = [
    ["project", projectPath],
    ["user", userPath],
  ];
  for (const [layer, path] of layers) {
    if (!path) continue;
    const data = readLayerFile(path, layer);
    if (!data) continue;
    checkSchemaVersion(data, layer, path);
    mergeLayer(config, data, defaults, layer, sources, warn);
  }
  config[SCHEMA_KEY] = `${SCHEMA_PREFIX}${SUPPORTED_SCHEMA}`;
  return { config, sources };
}
