const SCHEMA_VERSION = "cfg-schema-v4";
const VERSION_RE = /^cfg-schema-v(\d+)$/;

function versionNumber(value) {
  const match = VERSION_RE.exec(value);
  return match ? Number(match[1]) : null;
}

function readLayer(name, path) {
  if (!path) return null;
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`Invalid JSON in ${name} config ${path}: ${err.message}`);
  }
  if (data === null || typeof data !== "object" || Array.isArray(data)) {
    throw new Error(`The ${name} config ${path} must contain a JSON object`);
  }
  if ("schemaVersion" in data) {
    const declared = versionNumber(data.schemaVersion);
    if (declared === null) {
      throw new Error(`The ${name} config ${path} has an invalid schemaVersion: ${data.schemaVersion}`);
    }
    if (declared > versionNumber(SCHEMA_VERSION)) {
      throw new Error(
        `The ${name} config ${path} declares ${data.schemaVersion}, newer than supported ${SCHEMA_VERSION}`,
      );
    }
  }
  return data;
}

/**
 * Load config in three layers: defaults, project file, user file (later wins).
 * `schema` maps each known key to a type name ("string", "number", "boolean",
 * "object", "array"). Unknown keys warn and are kept; they never throw.
 *
 * @returns {{ config: object, sources: Record<string, string>, warnings: string[], schemaVersion: string }}
 */
export function loadConfig({ defaults = {}, projectPath, userPath, schema = {} } = {}) {
  const layers = [
    ["defaults", defaults],
    ["project", readLayer("project", projectPath)],
    ["user", readLayer("user", userPath)],
  ];
  const config = {};
  const sources = {};
  const warnings = [];

  for (const [layer, data] of layers) {
    if (!data) continue;
    for (const [key, value] of Object.entries(data)) {
      if (key === "schemaVersion") continue;
      if (layer !== "defaults" && !(key in schema)) {
        warnings.push(`Unknown config key "${key}" in ${layer} layer`);
      }
      config[key] = value;
      sources[key] = layer;
    }
  }

  for (const [key, type] of Object.entries(schema)) {
    if (!(key in config)) continue;
    const value = config[key];
    const actual = Array.isArray(value) ? "array" : value === null ? "null" : typeof value;
    if (actual !== type) {
      throw new Error(`Config key "${key}" (from ${sources[key]} layer) must be ${type}, got ${actual}`);
    }
  }

  return { config, sources, warnings, schemaVersion: SCHEMA_VERSION };
}
