import { readFileSync } from "node:fs";

const SCHEMA_VERSION = 4;
const SCHEMA_ID = `cfg-schema-v${SCHEMA_VERSION}`;
const VERSION_KEY = "schema";

const isPlainObject = (v) =>
  v !== null && typeof v === "object" && !Array.isArray(v);

const typeOf = (v) => (Array.isArray(v) ? "array" : v === null ? "null" : typeof v);

function readLayer(path, layer) {
  if (!path) return null;
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`${layer} config ${path} is not valid JSON: ${err.message}`);
  }
  if (!isPlainObject(data)) {
    throw new Error(`${layer} config ${path} must be a JSON object`);
  }
  if (VERSION_KEY in data) {
    const declared = data[VERSION_KEY];
    const match = typeof declared === "string" && /^cfg-schema-v(\d+)$/.exec(declared);
    if (!match) {
      throw new Error(`${layer} config ${path} has an invalid ${VERSION_KEY} value: ${JSON.stringify(declared)}`);
    }
    if (Number(match[1]) > SCHEMA_VERSION) {
      throw new Error(
        `${layer} config ${path} declares ${declared}, newer than supported ${SCHEMA_ID}`,
      );
    }
    delete data[VERSION_KEY];
  }
  return data;
}

// Merge one layer into `config`, validating against `defaults` (the schema).
function applyLayer(config, sources, defaults, data, layer, warnings, prefix = "") {
  for (const [key, value] of Object.entries(data)) {
    const path = prefix + key;
    if (!Object.hasOwn(defaults, key)) {
      warnings.push({ key: path, layer, message: `unknown key "${path}" in ${layer} layer` });
      continue;
    }
    const expected = defaults[key];
    if (isPlainObject(expected)) {
      if (!isPlainObject(value)) {
        throw new Error(`${layer} layer: "${path}" must be an object, got ${typeOf(value)}`);
      }
      applyLayer(config[key], sources, expected, value, layer, warnings, `${path}.`);
      continue;
    }
    if (typeOf(value) !== typeOf(expected)) {
      throw new Error(
        `${layer} layer: "${path}" must be ${typeOf(expected)}, got ${typeOf(value)}`,
      );
    }
    config[key] = value;
    sources[path] = layer;
  }
}

function seed(defaults, sources, prefix = "") {
  const out = {};
  for (const [key, value] of Object.entries(defaults)) {
    const path = prefix + key;
    if (isPlainObject(value)) {
      out[key] = seed(value, sources, `${path}.`);
    } else {
      out[key] = structuredClone(value);
      sources[path] = "default";
    }
  }
  return out;
}

/**
 * Load config in three layers: built-in defaults, project file, user file.
 * The defaults object doubles as the schema: its keys are the known keys and
 * its value types are the expected types. Unknown keys warn, never throw.
 * Files declaring a schema newer than cfg-schema-v4 are refused.
 *
 * @param {{ defaults: object, projectPath?: string, userPath?: string }} options
 * @returns {{ config: object, sources: Record<string,string>, warnings: object[], schema: string }}
 */
export function loadConfig({ defaults, projectPath, userPath } = {}) {
  if (!isPlainObject(defaults)) {
    throw new TypeError("loadConfig: `defaults` object is required");
  }
  const sources = {};
  const warnings = [];
  const config = seed(defaults, sources);
  for (const [layer, path] of [["project", projectPath], ["user", userPath]]) {
    const data = readLayer(path, layer);
    if (data) applyLayer(config, sources, defaults, data, layer, warnings);
  }
  return { config, sources, warnings, schema: SCHEMA_ID };
}
