import { readFileSync } from "node:fs";

const SCHEMA_VERSION = "cfg-schema-v4";
const VERSION_RE = /^cfg-schema-v(\d+)$/;
const MAX_VERSION = Number(VERSION_RE.exec(SCHEMA_VERSION)[1]);

function readLayer(path, layer) {
  if (!path) return null;
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw new Error(`Cannot read ${layer} config ${path}: ${err.message}`);
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`Invalid JSON in ${layer} config ${path}: ${err.message}`);
  }
  if (data === null || typeof data !== "object" || Array.isArray(data)) {
    throw new Error(`${layer} config ${path} must be a JSON object`);
  }
  return data;
}

function checkVersion(data, layer, path) {
  if (!("schemaVersion" in data)) return;
  const m = VERSION_RE.exec(String(data.schemaVersion));
  if (!m) {
    throw new Error(`${layer} config ${path} has unrecognized schemaVersion "${data.schemaVersion}"`);
  }
  if (Number(m[1]) > MAX_VERSION) {
    throw new Error(
      `${layer} config ${path} declares ${data.schemaVersion}, newer than supported ${SCHEMA_VERSION}`,
    );
  }
}

/**
 * Load config in three layers: defaults, project file, user file (later wins).
 * The merged result is checked against `schema`, a map of key -> validator
 * (a typeof string such as "string", or a function returning true when valid).
 * Unknown keys warn (naming key and layer) and are kept; they never throw.
 *
 * @returns {{ config: object, sources: Record<string,string>, warnings: string[], schemaVersion: string }}
 */
export function loadConfig({ defaults = {}, schema = {}, projectPath, userPath } = {}) {
  const layers = [{ name: "defaults", path: null, data: defaults }];
  for (const [name, path] of [["project", projectPath], ["user", userPath]]) {
    const data = readLayer(path, name);
    if (data) {
      checkVersion(data, name, path);
      layers.push({ name, path, data });
    }
  }

  const config = {};
  const sources = {};
  const warnings = [];

  for (const { name, data } of layers) {
    for (const [key, value] of Object.entries(data)) {
      if (key === "schemaVersion") continue;
      if (!Object.hasOwn(schema, key)) {
        warnings.push(`Unknown config key "${key}" in ${name} layer`);
      }
      config[key] = value;
      sources[key] = name;
    }
  }

  for (const [key, rule] of Object.entries(schema)) {
    if (!Object.hasOwn(config, key)) continue;
    const ok = typeof rule === "function" ? rule(config[key]) : typeof config[key] === rule;
    if (!ok) {
      throw new Error(`Invalid value for "${key}" (set by ${sources[key]} layer)`);
    }
  }

  return { config, sources, warnings, schemaVersion: SCHEMA_VERSION };
}
